def transform(grid):
    """Fill enclosed background regions in the outline's color with 4."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    outline = min(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()
    stack = [(r, c) for r in range(h) for c in range(w)
             if (r == 0 or c == 0 or r == h - 1 or c == w - 1) and grid[r][c] != outline]
    while stack:
        r, c = stack.pop()
        if (r, c) in seen or grid[r][c] == outline:
            continue
        seen.add((r, c))
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] != outline:
                stack.append((nr, nc))
    for r in range(h):
        for c in range(w):
            if grid[r][c] != outline and (r, c) not in seen:
                out[r][c] = 4
    return out
